    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = 0
    if LAST_ENTRY_TIME_KEY not in state:
        state[LAST_ENTRY_TIME_KEY] = None

    # Get MACD signal
    macd_line, signal_line, _ = ind.macd(hist.close, 8, 17, 9)
    macd_cross = (macd_line[-1] > signal_line[-1]) != (macd_line[-2] > signal_line[-2])

    # Determine direction
    if macd_cross:
        if macd_line[-1] > signal_line[-1]:
            direction = 1  # Long
        else:
            direction = -1  # Short
    else:
        direction = 0  # No change

    # Apply filter (no filter in this case)
    if direction != 0:
        if state[COOLDOWN_KEY] > 0:
            direction = 0  # Cooldown in progress
        elif state[DAILY_CAP_KEY] >= 1:
            direction = 0  # Daily cap reached
        else:
            # Check daily cap
            if hist.time[-1] // (24 * 60 * 60 * 1000) != state[LAST_ENTRY_TIME_KEY] // (24 * 60 * 60 * 1000):
                state[DAILY_CAP_KEY] = 0
            state[DAILY_CAP_KEY] += 1
            state[LAST_ENTRY_TIME_KEY] = hist.time[-1]

    # Determine target position
    if direction != 0:
        if state[ENTRY_ATR_KEY] is None:
            state[ENTRY_ATR_KEY] = ind.atr(hist, 14)[-1]
            state[ENTRY_PRICE_KEY] = hist.close[-1]
            state[LAST_SIGNAL_KEY] = direction
            state[COOLDOWN_KEY] = 4
        else:
            if direction == state[LAST_SIGNAL_KEY]:
                # Pyramid
                if hist.close[-1] >= state[ENTRY_PRICE_KEY] + 2 * state[ENTRY_ATR_KEY]:
                    pos += 0.25
                    pos = min(pos, 1.0)
            else:
                # Opposite MACD cross or time stop
                pos = 0
                state[ENTRY_ATR_KEY] = None
                state[ENTRY_PRICE_KEY] = None
                state[LAST_SIGNAL_KEY] = None
                state[COOLDOWN_KEY] = 4

    # Determine stop and take levels
    if pos != 0:
        entry_atr = state[ENTRY_ATR_KEY]
        entry_price = state[ENTRY_PRICE_KEY]
        stop = entry_price - entry_atr if pos > 0 else entry_price + entry_atr
        take = entry_price + 2 * entry_atr if pos > 0 else entry_price - 2 * entry_atr
    else:
        stop = None
        take = None

    # Round target to 0.05 grid
    target = round(pos, 2)

    return {"target": target, "stop": stop, "take": take}

