    if LAST_ENTRY_KEY not in state:
        state[LAST_ENTRY_KEY] = None
    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = False
    if DAILY_CAP_COUNT_KEY not in state:
        state[DAILY_CAP_COUNT_KEY] = 0

