    if state[DAILY_CAP_KEY]:
        if hist.time[t] // (24 * 60 * 60 * 1000) != state[LAST_ENTRY_KEY] // (24 * 60 * 60 * 1000):
            state[DAILY_CAP_KEY] = False
            state[DAILY_CAP_COUNT_KEY] = 0
        else:
            state[DAILY_CAP_COUNT_KEY] += 1
            if state[DAILY_CAP_COUNT_KEY] >= 1:
                return {"target": pos, "stop": None, "take": None}

    # Calculate ATR and entry ATR
    atr = ind.atr(hist, 14)
    entry_atr = atr[t]

    # Check for breakout
    box_top = ind.highest(hist.close, 16)[t]
    box_bottom = ind.lowest(hist.close, 16)[t]
    box_height = box_top - box_bottom

    if box_height <= 3 * entry_atr:
        if hist.close[t] > box_top and pos == 0:
            state[ENTRY_ATR_KEY] = entry_atr
            state[ENTRY_PRICE_KEY] = hist.close[t]
            state[COOLDOWN_KEY] = 4
            state[LAST_ENTRY_KEY] = hist.time[t]
            state[DAILY_CAP_KEY] = True
            state[DAILY_CAP_COUNT_KEY] = 1
            return {"target": 1.0, "stop": hist.close[t] - 1.5 * entry_atr, "take": hist.close[t] + 3 * entry_atr}
        elif hist.close[t] < box_bottom and pos == 0:
            state[ENTRY_ATR_KEY] = entry_atr
            state[ENTRY_PRICE_KEY] = hist.close[t]
            state[COOLDOWN_KEY] = 4
            state[LAST_ENTRY_KEY] = hist.time[t]
            state[DAILY_CAP_KEY] = True
            state[DAILY_CAP_COUNT_KEY] = 1
            return {"target": -1.0, "stop": hist.close[t] + 1.5 * entry_atr, "take": hist.close[t] - 3 * entry_atr}

    # Check for cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for take profit and partial take
    if pos != 0:
        if hist.close[t] >= state[ENTRY_PRICE_KEY] + 3 * entry_atr:
            return {"target": pos / 2, "stop": None, "take": None}
        elif hist.close[t] <= state[ENTRY_PRICE_KEY] - 3 * entry_atr:
            return {"target": -pos / 2, "stop": None, "take": None}

    # Check for trailing stop
    if pos != 0:
        if pos > 0:
            trailing_stop = state[ENTRY_PRICE_KEY] + 1.5 * entry_atr
        else:
            trailing_stop = state[ENTRY_PRICE_KEY] - 1.5 * entry_atr

        if pos > 0 and hist.high[t] > trailing_stop:
            trailing_stop = hist.high[t]
        elif pos < 0 and hist.low[t] < trailing_stop:
            trailing_stop = hist.low[t]

        return {"target": pos, "stop": trailing_stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

