import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Signal: MACD(12, 26, 9) crossover
    macd_line, signal_line, _ = ind.macd(hist.close, 12, 26, 9)
    signal = np.where(macd_line > signal_line, 1, 0) - np.where(macd_line < signal_line, 1, 0)

    # Direction: Long only
    if signal[-1] == 1:
        target = 1.0
    elif signal[-1] == -1:
        target = -1.0
    else:
        target = pos

    # Filter: No filter
    if target != pos:
        return {"target": target, "stop": None, "take": None}

    # Sizing: ATR risk, 0.25% of equity per 2 ATR, capped at 1.0 and floored at 0.05
    entry_price = hist.close[-1]
    entry_atr = ind.atr(hist, 14)[-1]
    position_fraction = 0.0025 * entry_price / (2 * entry_atr)
    position_fraction = max(0.05, min(1.0, position_fraction))

    # Risk: Trailing box, 2 ATR stop, 3 ATR target, ratchet on 1 ATR profit, breakeven on 1.5 ATR profit
    if 'entry_price' not in state:
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['stop_price'] = entry_price - 2 * entry_atr
        state['target_price'] = entry_price + 3 * entry_atr
        state['ratcheted'] = False
        state['breakeven'] = False

    current_price = hist.close[-1]
    if current_price >= state['target_price']:
        target = 0.0
        state['ratcheted'] = True
    elif current_price >= state['entry_price'] + 1.5 * state['entry_atr']:
        state['stop_price'] = state['entry_price']
        state['breakeven'] = True
    elif current_price <= state['stop_price']:
        target = 0.0
    elif current_price >= state['entry_price']:
        if not state['ratcheted']:
            state['target_price'] += state['entry_atr']
            state['ratcheted'] = True

    return {"target": target, "stop": state['stop_price'], "take": state['target_price']}

