    sma_200 = ind.sma(hist.close, 200)
    signal = (sma_5[-1] > sma_200[-1]) and (sma_5[-2] <= sma_200[-2])

    # Direction: long_short
    if 'direction' not in state:
        state['direction'] = 'long'

    # Filter: no_filter
    if not signal:
        return {"target": pos, "stop": None, "take": None}

    # Sizing: 1% of equity per 1 ATR, capped at 1.0 and floored at 0.05
    atr_14 = ind.atr(hist, 14)
    entry_price = hist.close[-1]
    position_fraction = max(0.05, min(1.0, 0.01 * entry_price / (1 * atr_14[-1])))

    # Risk: breakeven and trailing stop
    if 'entry_price' not in state:
        state['entry_price'] = entry_price
        state['entry_atr'] = atr_14[-1]
        state['stop_price'] = entry_price - 1.5 * state['entry_atr']
        state['take_price'] = entry_price + 2.0 * state['entry_atr']

    if signal and state['direction'] == 'long':
        state['direction'] = 'short'
        return {"target": 0, "stop": None, "take": None}
    elif signal and state['direction'] == 'short':
        state['direction'] = 'long'
        return {"target": 0, "stop": None, "take": None}

    if hist.close[-1] >= state['entry_price'] + 1.5 * state['entry_atr']:
