        target = position_fraction if target > 0 else -position_fraction

    # Risk: Hard stop at 1.5 ATR from entry
    if 'entry_price' not in state:
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['stop_price'] = entry_price - 1.5 * entry_atr if target > 0 else entry_price + 1.5 * entry_atr
    else:
        if target != pos:
            state['entry_price'] = entry_price
            state['entry_atr'] = entry_atr
            state['stop_price'] = entry_price - 1.5 * entry_atr if target > 0 else entry_price + 1.5 * entry_atr

    stop = state['stop_price']

    # Risk: Time stop at the open after 32 bars
    if 'time_stop_bar' not in state:
        state['time_stop_bar'] = hist.time[-1] + 32 * 15 * 60 * 1000
    if hist.time[-1] >= state['time_stop_bar']:
        target = 0.0

    return {"target": target, "stop": stop, "take": None}

