def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR_KEY = 'entry_atr'
    ENTRY_PRICE_KEY = 'entry_price'
    BOX_ANCHOR_KEY = 'box_anchor'
    BOX_STOP_KEY = 'box_stop'
    BOX_TARGET_KEY = 'box_target'
    LAST_SIGNAL_KEY = 'last_signal'
    COOLDOWN_KEY = 'cooldown'
    DAILY_CAP_KEY = 'daily_cap'
    LAST_SIGNAL_DATE_KEY = 'last_signal_date'

    # Get current bar index
    t = len(hist) - 1

    # Initialize state if not already initialized
    if ENTRY_ATR_KEY not in state:
        state[ENTRY_ATR_KEY] = None
        state[ENTRY_PRICE_KEY] = None
        state[BOX_ANCHOR_KEY] = None
        state[BOX_STOP_KEY] = None
        state[BOX_TARGET_KEY] = None
        state[LAST_SIGNAL_KEY] = None
        state[COOLDOWN_KEY] = 0
        state[DAILY_CAP_KEY] = 0
        state[LAST_SIGNAL_DATE_KEY] = None

    # Check daily cap
    if state[DAILY_CAP_KEY] > 0:
        if hist.time[t] // (24 * 3600 * 1000) != state[LAST_SIGNAL_DATE_KEY]:
            state[DAILY_CAP_KEY] = 0
        else:
            return {"target": pos, "stop": None, "take": None}

    # Check cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Calculate ATR
    atr = ind.atr(hist, 14)[-1]

    # Donchian breakout signal
    if ind.highest(hist.close, 192)[-1] < hist.close[-1]:
        signal = 1.0
    elif ind.lowest(hist.close, 192)[-1] > hist.close[-1]:
        signal = -1.0
    else:
        signal = 0.0

    # Apply trend filter
    if signal != 0.0:
        htf_close = hist.htf(60).close
        htf_ema = ind.ema(htf_close, 50)[-1]
        if signal > 0 and htf_close[-1] <= htf_ema:
            signal = 0.0
        elif signal < 0 and htf_close[-1] >= htf_ema:
            signal = 0.0

    # Apply cooldown if signal is opposite to current position
    if signal != 0.0 and signal * pos < 0:
        state[COOLDOWN_KEY] = 4
        return {"target": pos, "stop": None, "take": None}

    # Execute entry
    if signal != 0.0 and pos == 0.0:
        entry_price = hist.close[-1]
        entry_atr = atr
        box_anchor = entry_price
        box_stop = entry_price - 2 * entry_atr
        box_target = entry_price + 2 * entry_atr
        state[ENTRY_ATR_KEY] = entry_atr
        state[ENTRY_PRICE_KEY] = entry_price
        state[BOX_ANCHOR_KEY] = box_anchor
        state[BOX_STOP_KEY] = box_stop
        state[BOX_TARGET_KEY] = box_target
        state[LAST_SIGNAL_KEY] = signal
        state[DAILY_CAP_KEY] += 1
        state[LAST_SIGNAL_DATE_KEY] = hist.time[t] // (24 * 3600 * 1000)
        return {"target": signal * 0.05, "stop": box_stop, "take": box_target}

    # Execute exit
    if pos != 0.0:
        if hist.low[-1] <= state[BOX_STOP_KEY]:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.high[-1] >= state[BOX_TARGET_KEY]:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.close[-1] >= state[ENTRY_PRICE_KEY] + 1.5 * state[ENTRY_ATR_KEY]:
            return {"target": pos / 2, "stop": None, "take": None}
        if t - state[LAST_SIGNAL_KEY] >= 32:
            return {"target": 0.0, "stop": None, "take": None}

    # Update box
    if pos != 0.0:
        if hist.close[-1] >= state[BOX_ANCHOR_KEY] + state[ENTRY_ATR_KEY]:
            state[BOX_ANCHOR_KEY] += state[ENTRY_ATR_KEY]
            state[BOX_STOP_KEY] += state[ENTRY_ATR_KEY]
            state[BOX_TARGET_KEY] += state[ENTRY_ATR_KEY]

    return {"target": pos, "stop": state[BOX_STOP_KEY], "take": state[BOX_TARGET_KEY]}

