def strategy(hist, state, pos, ind) -> dict:
    # Signal: 192-bar Donchian breakout
    entry_price = hist.close[-1]
    entry_high = ind.highest(hist.high, 192)[-1]
    entry_low = ind.lowest(hist.low, 192)[-1]
    breakout = entry_price > entry_high
    if breakout:
        target = 1.0
    else:
        target = 0.0

    # Filter: 1-hour EMA 50 trend filter
    htf_close = hist.htf(60).close
    htf_ema_50 = ind.ema(htf_close, 50)[-1]
    if breakout and hist.close[-2] <= htf_ema_50:
        target = 1.0
    elif not breakout and hist.close[-2] >= htf_ema_50:
        target = 0.0

    # Sizing: Volatility-scaled at risk 0.25% of equity per 3 ATR, capped between 0.05 and 1.0
    atr_14 = ind.atr(hist, 14)[-1]
    position_size = 0.0025 * hist.close[-1] / (3 * atr_14)
    position_size = max(0.05, min(1.0, position_size))

    # Risk management: Trailing box, breakeven, time stop
    if 'entry_price' not in state:
        state['entry_price'] = entry_price
        state['entry_atr'] = atr_14
        state['stop_price'] = entry_price - state['entry_atr']
        state['target_price'] = entry_price + 3 * state['entry_atr']
        state['box_shifted'] = 0
        state['bars_since_entry'] = 0

    if pos != 0:
        state['bars_since_entry'] += 1

    if pos > 0:
        if hist.high[-1] > state['target_price']:
            target = 0.0
        elif hist.low[-1] <= state['stop_price']:
            target = 0.0
        elif hist.close[-1] >= state['entry_price'] + 0.5 * state['entry_atr']:
            state['stop_price'] = state['entry_price']
        elif hist.close[-1] >= state['entry_price'] + 2 * state['entry_atr']:
            state['stop_price'] = state['entry_price'] - state['entry_atr']
            state['target_price'] = state['entry_price'] + 3 * state['entry_atr']
            state['box_shifted'] += 1
    elif pos < 0:
        if hist.low[-1] < state['target_price']:
            target = 0.0
        elif hist.high[-1] >= state['stop_price']:
            target = 0.0
        elif hist.close[-1] <= state['entry_price'] - 0.5 * state['entry_atr']:
            state['stop_price'] = state['entry_price']
        elif hist.close[-1] <= state['entry_price'] - 2 * state['entry_atr']:
            state['stop_price'] = state['entry_price'] + state['entry_atr']
            state['target_price'] = state['entry_price'] - 3 * state['entry_atr']
            state['box_shifted'] += 1

    if state['bars_since_entry'] >= 256:
        target = 0.0

    return {
        "target": target,
        "stop": state['stop_price'],
        "take": state['target_price']
    }

