def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    ENTRY_PRICE = hist.close[-1]
    ATR_3 = 3 * ENTRY_ATR
    COOLDOWN = 16
    DAILY_CAP = 1

    # State management
    if 'last_entry' not in state:
        state['last_entry'] = None
    if 'last_flat' not in state:
        state['last_flat'] = None
    if 'daily_count' not in state:
        state['daily_count'] = 0

    # Cooldown check
    if state['last_entry'] is not None and hist.time[-1] - state['last_entry'] < COOLDOWN * 60 * 15 * 1000:
        return {"target": pos, "stop": None, "take": None}

    # Daily cap check
    if hist.time[-1] - state['last_flat'] < 24 * 60 * 60 * 1000:
        state['daily_count'] += 1
        if state['daily_count'] > DAILY_CAP:
            return {"target": pos, "stop": None, "take": None}
    else:
        state['daily_count'] = 0

    # Signal generation
    if hist.close[-1] > ind.highest(hist.close, 20)[-1]:
        signal = 1
    elif hist.close[-1] < ind.lowest(hist.close, 20)[-1]:
        signal = -1
    else:
        return {"target": pos, "stop": None, "take": None}

    # Position sizing
    if pos == 0:
        target = 0.25
    else:
        target = pos + 0.5 if pos * signal > 0 else pos - 0.5

    # Trailing stop
    if 'highs' not in state:
        state['highs'] = []
    if 'lows' not in state:
        state['lows'] = []

    if signal == 1:
        state['highs'].append(hist.high[-1])
        stop = min(state['highs']) - ATR_3
    else:
        state['lows'].append(hist.low[-1])
        stop = max(state['lows']) + ATR_3

    # Time stop
    if 'time_stop' not in state:
        state['time_stop'] = None
    if signal != 0:
        state['time_stop'] = hist.time[-1]

    if state['time_stop'] is not None and hist.time[-1] - state['time_stop'] >= 128 * 60 * 15 * 1000:
        return {"target": 0, "stop": None, "take": None}

    # Take profit
    if signal == 1 and hist.close[-1] >= ENTRY_PRICE + 2 * ENTRY_ATR:
        return {"target": 0, "stop": None, "take": None}
    elif signal == -1 and hist.close[-1] <= ENTRY_PRICE - 2 * ENTRY_ATR:
        return {"target": 0, "stop": None, "take": None}

    return {"target": target, "stop": stop, "take": None}

