    if signal and filter_passed:
        state['entry_price'] = ENTRY_PRICE
        state['stop_price'] = ENTRY_PRICE - ATR_1X
        state['target_price'] = ENTRY_PRICE + ATR_3X
        state['box_anchor'] = ENTRY_PRICE
        state['last_add_price'] = ENTRY_PRICE
        state['last_add_bar'] = len(hist) - 1
    elif pos != 0:
        if hist.close[-1] >= state['entry_price'] + ATR_2X:
            state['box_anchor'] += ATR_2X
            state['target_price'] += ATR_2X
        if hist.close[-1] >= state['entry_price'] + ATR_2X:
            state['stop_price'] = state['entry_price']
        if hist.close[-1] >= state['entry_price'] + ATR_2X:
            target_pos = pos / 2

