    if 'last_entry_day' not in state:
        state['last_entry_day'] = None
    current_day = hist.time[-1] // (24 * 60 * 60 * 1000)
    if current_day != state['last_entry_day']:
        state['last_entry_day'] = current_day
    else:
        target_pos = 0

    # Round target position to 0.05 grid
    target_pos = round(target_pos * 20) / 20

    return {
        "target": target_pos,
        "stop": state['stop_price'],
        "take": state['target_price']
    }

