        state['last_entry_time'] = 0
    if 'daily_count' not in state:
        state['daily_count'] = 0

    # Daily cap check
    if hist.time[-1] // (24 * 3600 * 1000) != state['last_entry_time'] // (24 * 3600 * 1000):
        state['daily_count'] = 0

    # Check if daily cap is reached
    if state['daily_count'] >= DAILY_CAP:
        return {"target": pos, "stop": None, "take": None}

    # MACD cross signal
    macd_line, signal_line, _ = ind.macd(hist.close, 5, 35, 5)
    macd_cross_long = macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]
    macd_cross_short = macd_line[-1] < signal_line[-1] and macd_line[-2] >= signal_line[-2]

    # 4-hour trend filter
    htf_close = hist.htf(240).close
    htf_ema = ind.ema(htf_close, 50)
    trend_long = htf_close[-1] > htf_ema[-1]
    trend_short = htf_close[-1] < htf_ema[-1]

    # Entry conditions
    if (macd_cross_long and trend_long) or (macd_cross_short and trend_short):
        if pos == 0:
            state['last_entry_time'] = hist.time[-1]
            state['daily_count'] += 1
            position_size = min(MAX_POSITION, ENTRY_PRICE * RISK_PER_ATR * ENTRY_ATR)
            if macd_cross_long:
                return {"target": position_size, "stop": ENTRY_PRICE - ENTRY_ATR, "take": ENTRY_PRICE + 2 * ENTRY_ATR}
            else:
                return {"target": -position_size, "stop": ENTRY_PRICE + ENTRY_ATR, "take": ENTRY_PRICE - 2 * ENTRY_ATR}

    # Exit conditions
    if pos > 0:
        if hist.low[-1] <= state['stop']:
            return {"target": 0, "stop": None, "take": None}
        if hist.high[-1] >= state['take']:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        if hist.high[-1] >= state['stop']:
            return {"target": 0, "stop": None, "take": None}
        if hist.low[-1] <= state['take']:
            return {"target": 0, "stop": None, "take": None}

