def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    ENTRY_PRICE = hist.close[-1]
    ATR_2X = 2 * ENTRY_ATR

    # Donchian breakout signal
    high_192 = ind.highest(hist.high, 192)[-1]
    low_192 = ind.lowest(hist.low, 192)[-1]

    # Determine target position
    if pos == 0:
        if hist.close[-1] > high_192:
            target = 1.0
        elif hist.close[-1] < low_192:
            target = -1.0
        else:
            target = pos
    else:
        target = pos

    # Determine stop and take levels
    if pos > 0:
        stop = ENTRY_PRICE - ATR_2X
        take = ENTRY_PRICE + ATR_2X
    elif pos < 0:
        stop = ENTRY_PRICE + ATR_2X
        take = ENTRY_PRICE - ATR_2X
    else:
        stop = None
        take = None

    # Round target to 0.05 grid
    target = round(target, 2) if target != 0 else 0

    return {"target": target, "stop": stop, "take": take}

