def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    ENTRY_PRICE = hist.close[-1]
    ATR_14 = ind.atr(hist, 14)[-1]

    # Signal
    macd_line, signal_line, _ = ind.macd(hist.close, 8, 17, 9)
    signal = macd_line[-1] > signal_line[-1] and macd_line[-2] <= signal_line[-2]

    # Filter
    htf_close = hist.htf(60).close[-1]
    htf_ema = ind.ema(hist.htf(60).close, 20)[-1]
    filter_passed = htf_close > htf_ema

    # Sizing
    if pos == 0:
        position_size = 0.25 * hist.close[-1] / (1 * ATR_14)
        position_size = max(0.05, min(1.0, position_size))
    else:
        position_size = pos

    # Risk
    if pos > 0:
        stop_price = ENTRY_PRICE - ENTRY_ATR
        take_price = ENTRY_PRICE + 2 * ENTRY_ATR
        if hist.low[-1] <= stop_price:
            return {"target": 0, "stop": None, "take": None}
        if hist.high[-1] >= take_price:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        stop_price = ENTRY_PRICE + ENTRY_ATR
        take_price = ENTRY_PRICE - 2 * ENTRY_ATR
        if hist.high[-1] >= stop_price:
            return {"target": 0, "stop": None, "take": None}
        if hist.low[-1] <= take_price:
            return {"target": 0, "stop": None, "take": None}

    # Breakeven
    if pos > 0 and hist.close[-1] >= ENTRY_PRICE + 2 * ENTRY_ATR:
        stop_price = ENTRY_PRICE

    # Cooldown
    if 'last_flat' in state and hist.time[-1] - state['last_flat'] < 4 * 15 * 60 * 1000:
        return {"target": pos, "stop": None, "take": None}

    # Daily cap
    if 'last_entry' in state and hist.time[-1] - state['last_entry'] < 24 * 60 * 60 * 1000:
        return {"target": pos, "stop": None, "take": None}

    # Entry
    if signal and filter_passed:
        state['last_entry'] = hist.time[-1]
        if pos == 0:
            state['last_flat'] = hist.time[-1]
        return {"target": position_size, "stop": stop_price, "take": take_price}

    return {"target": pos, "stop": stop_price, "take": take_price}

