    macd_line, signal_line, _ = ind.macd(hist.close, 5, 35, 5)
    signal = (macd_line[-1] > signal_line[-1]) and (macd_line[-2] <= signal_line[-2])

    # Direction: Long only
    if pos != 0:
        return {"target": 0, "stop": None, "take": None}

    # Filter: Daily cap
    if "last_entry" in state and state["last_entry"] >= hist.time[-1] - 24 * 60 * 60 * 1000:
        return {"target": pos, "stop": None, "take": None}

    # Sizing: Pyramid
    if signal:
        entry_price = hist.close[-1]
        entry_atr = ind.atr(hist, 14)[-1]
        target = 0.25 * hist.close[-1] / (1 * entry_atr)
        if pos == 0:
            state["last_entry"] = hist.time[-1]
            state["target"] = target
            state["add_price"] = entry_price
        else:
            if hist.close[-1] >= state["add_price"] + 2 * entry_atr:
                state["target"] += 0.25 * hist.close[-1] / (1 * entry_atr)
                state["add_price"] = hist.close[-1]
                state["target"] = min(state["target"], 1.0)

        # Risk: Time stop
        if "time_stop" not in state:
            state["time_stop"] = hist.time[-1] + 32 * 15 * 60 * 1000
        if hist.time[-1] >= state["time_stop"]:
            return {"target": 0, "stop": None, "take": None}

        # Stop and take
        stop = entry_price - entry_atr
