            state[LAST_SIGNAL_DATE_KEY] = hist.time[t]
            state[DAILY_CAP_KEY] += 1
            target = 0.5
            stop = entry_price - 2 * entry_atr
            take = entry_price + 3 * entry_atr
            return {"target": target, "stop": stop, "take": take}

    # Check for pyramid
    if state[LAST_SIGNAL_KEY] == 'long' and pos > 0:
        last_add_price = state.get('last_add_price', entry_price)
        if hist.close[-1] >= last_add_price + entry_atr:
            target += 0.5
            state['last_add_price'] = hist.close[-1]
            if target > 1.0:
                target = 1.0

    # Check for trailing stop
    if state[LAST_SIGNAL_KEY] == 'long' and pos > 0:
        hwm = ind.highest(hist.high, t + 1)[-1]
        stop = hwm - 3 * entry_atr

    # Check for take profit
    if state[LAST_SIGNAL_KEY] == 'long' and pos > 0:
        if hist.close[-1] >= entry_price + 3 * entry_atr:
            target = 0

    # Check for cooldown
    if state[LAST_SIGNAL_KEY] == 'long' and pos == 0:
        state[COOLDOWN_KEY] = 4

    return {"target": pos, "stop": stop, "take": take}

