    elif ema_20[-1] < ema_200[-1] and ema_20[-2] >= ema_200[-2]:
        signal = -1.0  # Death cross, go short

    # Filter: No filter
    if signal == 0.0:
        return {"target": pos, "stop": None, "take": None}

