    entry_price = hist.close[-1]
    entry_atr = ind.atr(hist, 14)[-1]
    position_fraction = 0.5 * entry_price / (1 * entry_atr)
    position_fraction = max(0.05, min(1.0, position_fraction))

    # Risk: Box shift and trailing stop
    if 'entry_price' not in state:
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['stop_price'] = entry_price - entry_atr
        state['target_price'] = entry_price + 2 * entry_atr
        state['box_shifted'] = 0

    if signal == 1.0:  # Long
        if hist.low[-1] <= state['stop_price']:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.high[-1] >= state['target_price']:
            state['target_price'] += entry_atr
            state['box_shifted'] += 1
        state['stop_price'] = max(state['stop_price'], hist.low[-1])
    elif signal == -1.0:  # Short
        if hist.high[-1] >= state['stop_price']:
            return {"target": 0.0, "stop": None, "take": None}
        if hist.low[-1] <= state['target_price']:
            state['target_price'] -= entry_atr
            state['box_shifted'] += 1
        state['stop_price'] = min(state['stop_price'], hist.high[-1])

    return {"target": pos + position_fraction * signal, "stop": state['stop_price'], "take": state['target_price']}

