        else:
            state[BREAKOUT_LEVEL_KEY] = breakout_low

    # Check if in cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check if armed
    if state[ARMED_KEY]:
        if hist.low[-1] <= state[BREAKOUT_LEVEL_KEY]:
            state[ARMED_KEY] = False
            if pos < 0:
