    # Check for breakout
    if hist.close[-1] > state[BREAKOUT_LEVEL_KEY]:
        state[ARMED_KEY] = True
        state[COOLDOWN_KEY] = 64
        if pos > 0:
            return {"target": 0, "stop": None, "take": None}
        else:
            return {"target": 1, "stop": None, "take": None}

    # Check for short breakout
    if hist.close[-1] < state[BREAKOUT_LEVEL_KEY]:
        state[ARMED_KEY] = True
        state[COOLDOWN_KEY] = 64
        if pos < 0:
            return {"target": 0, "stop": None, "take": None}
        else:
            return {"target": -1, "stop": None, "take": None}

    # Check for partial take profit
    if pos > 0 and hist.close[-1] >= state[BREAKOUT_LEVEL_KEY] + 3 * state[ENTRY_ATR_KEY]:
