    # Risk: partial_take
    if pos > 0 and hist.close[-1] >= entry_price + 3 * entry_atr:
        position_size /= 2

    # Determine target and stop
    if state['direction'] == 'long':
        if signal_long:
            state['direction'] = 'short'
