def strategy(hist, state, pos, ind) -> dict:
    # Signal: RSI(7) crosses back up through 25
    rsi = ind.rsi(hist.close, 7)
    signal = (rsi[-2] < 25) and (rsi[-1] >= 25)

    # Direction: Long only
    if signal and pos == 0:
        target = 1.0
        stop = hist.close[-1] - ind.atr(hist, 14)[-1]
        take = hist.close[-1] + 2 * ind.atr(hist, 14)[-1]
        return {"target": target, "stop": stop, "take": take}

    # Risk management
    if pos != 0:
        entry_price = hist.close[-2]
        entry_atr = ind.atr(hist, 14)[-2]

        # Take profit
        if hist.close[-1] >= entry_price + 2 * entry_atr:
            target = 0.5 * pos
            stop = None
            take = None
            return {"target": target, "stop": stop, "take": take}

        # Partial take
        if hist.close[-1] >= entry_price + 1.5 * entry_atr:
            target = 0.5 * pos
            stop = None
            take = None
            return {"target": target, "stop": stop, "take": take}

        # Cooldown
        if 'last_flat' in state and hist.time[-1] - state['last_flat'] < 16 * 15 * 60 * 1000:
            target = 0
            stop = None
            take = None
            return {"target": target, "stop": stop, "take": take}

        # Trailing stop
        if 'best_price' not in state:
            state['best_price'] = entry_price
        if hist.high[-1] > state['best_price']:
            state['best_price'] = hist.high[-1]
        stop = state['best_price'] - entry_atr

        # Time stop
        if 'time_stop' in state and hist.time[-1] - state['time_stop'] < 16 * 15 * 60 * 1000:
            target = 0
            stop = None
            take = None
            return {"target": target, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

