def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR_KEY = 'entry_atr'
    ENTRY_PRICE_KEY = 'entry_price'
    LAST_SIGNAL_KEY = 'last_signal'
    COOLDOWN_KEY = 'cooldown'
    DAILY_CAP_KEY = 'daily_cap'
    ENTRY_COUNT_KEY = 'entry_count'

    # Get current bar index
    t = len(hist) - 1

    # Initialize state if not already initialized
    if ENTRY_ATR_KEY not in state:
        state[ENTRY_ATR_KEY] = None
    if ENTRY_PRICE_KEY not in state:
        state[ENTRY_PRICE_KEY] = None
    if LAST_SIGNAL_KEY not in state:
        state[LAST_SIGNAL_KEY] = None
    if COOLDOWN_KEY not in state:
        state[COOLDOWN_KEY] = 0
    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = 0
    if ENTRY_COUNT_KEY not in state:
        state[ENTRY_COUNT_KEY] = 0

    # Get current ATR
    atr = ind.atr(hist, 14)[-1]

    # Check for cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for daily cap
    if state[DAILY_CAP_KEY] >= 2:
        return {"target": pos, "stop": None, "take": None}

    # Check for breakout signal
    if state[ENTRY_ATR_KEY] is None and hist.close[-1] > ind.highest(hist.close, 16)[-1] and hist.close[-1] > ind.highest(hist.close, 16)[-1] + 3 * atr:
        if hist.close[-2] <= ind.highest(hist.close, 16)[-2]:
            state[ENTRY_ATR_KEY] = atr
            state[ENTRY_PRICE_KEY] = hist.close[-1]
            state[LAST_SIGNAL_KEY] = 'long'
            state[COOLDOWN_KEY] = 4
            state[DAILY_CAP_KEY] += 1
            state[ENTRY_COUNT_KEY] += 1
            return {"target": 0.05, "stop": state[ENTRY_PRICE_KEY] - atr, "take": state[ENTRY_PRICE_KEY] + 2 * atr}

    # Check for breakout and retest signal
    if state[ENTRY_ATR_KEY] is not None and hist.close[-1] < ind.highest(hist.close, 16)[-1] and hist.close[-1] < ind.highest(hist.close, 16)[-1] - 3 * atr:
        if hist.close[-2] >= ind.highest(hist.close, 16)[-2]:
            state[ENTRY_ATR_KEY] = atr
            state[ENTRY_PRICE_KEY] = hist.close[-1]
            state[LAST_SIGNAL_KEY] = 'short'
            state[COOLDOWN_KEY] = 4
            state[DAILY_CAP_KEY] += 1
            state[ENTRY_COUNT_KEY] += 1
            return {"target": -0.05, "stop": state[ENTRY_PRICE_KEY] + atr, "take": state[ENTRY_PRICE_KEY] - 2 * atr}

    # Check for trailing stop
    if state[ENTRY_ATR_KEY] is not None:
        if state[LAST_SIGNAL_KEY] == 'long':
            if hist.high[-1] > state[ENTRY_PRICE_KEY] + 2 * state[ENTRY_ATR_KEY]:
                state[ENTRY_PRICE_KEY] = hist.high[-1]
                state[ENTRY_ATR_KEY] = atr
            return {"target": pos, "stop": state[ENTRY_PRICE_KEY] - state[ENTRY_ATR_KEY], "take": None}
        elif state[LAST_SIGNAL_KEY] == 'short':
            if hist.low[-1] < state[ENTRY_PRICE_KEY] - 2 * state[ENTRY_ATR_KEY]:
                state[ENTRY_PRICE_KEY] = hist.low[-1]
                state[ENTRY_ATR_KEY] = atr
            return {"target": pos, "stop": state[ENTRY_PRICE_KEY] + state[ENTRY_ATR_KEY], "take": None}

    # Check for partial take profit
    if state[ENTRY_ATR_KEY] is not None:
        if state[LAST_SIGNAL_KEY] == 'long' and hist.close[-1] >= state[ENTRY_PRICE_KEY] + 2 * state[ENTRY_ATR_KEY]:
            return {"target": pos / 2, "stop": None, "take": None}
        elif state[LAST_SIGNAL_KEY] == 'short' and hist.close[-1] <= state[ENTRY_PRICE_KEY] - 2 * state[ENTRY_ATR_KEY]:
            return {"target": pos / 2, "stop": None, "take": None}

    # No change
    return {"target": pos, "stop": None, "take": None}

