    # Check daily cap
    if state[DAILY_CAP_KEY]:
        if hist.time[t] // (24 * 60 * 60 * 1000) != state[DAILY_CAP_COUNT_KEY]:
            state[DAILY_CAP_KEY] = False
        else:
            return {"target": pos, "stop": None, "take": None}

    # Calculate entry ATR
    if state[ENTRY_ATR_KEY] is None:
        state[ENTRY_ATR_KEY] = ind.atr(hist, 14)[-1]

    # Calculate breakout level
    if state[BREAKOUT_LEVEL_KEY] is None:
        breakout_high = ind.highest(hist.high, 96)[-1]
        breakout_low = ind.lowest(hist.low, 96)[-1]
        if breakout_high > breakout_low:
            state[BREAKOUT_LEVEL_KEY] = breakout_high
        else:
            state[BREAKOUT_LEVEL_KEY] = breakout_low

    # Check for breakout
    if hist.close[t] > state[BREAKOUT_LEVEL_KEY]:
        if state[COOLDOWN_KEY] == 0:
            state[LAST_ENTRY_KEY] = t
            state[COOLDOWN_KEY] = 4
            state[DAILY_CAP_COUNT_KEY] = hist.time[t] // (24 * 60 * 60 * 1000)
            state[DAILY_CAP_KEY] = True
            return {"target": 1.0, "stop": state[ENTRY_ATR_KEY] * 1.5, "take": state[ENTRY_ATR_KEY] * 4.0}
    elif hist.close[t] < state[BREAKOUT_LEVEL_KEY]:
        if state[COOLDOWN_KEY] == 0:
            state[LAST_ENTRY_KEY] = t
            state[COOLDOWN_KEY] = 4
            state[DAILY_CAP_COUNT_KEY] = hist.time[t] // (24 * 60 * 60 * 1000)
            state[DAILY_CAP_KEY] = True
            return {"target": -1.0, "stop": state[ENTRY_ATR_KEY] * 1.5, "take": state[ENTRY_ATR_KEY] * 4.0}

    # Check for retest
    if pos > 0 and hist.low[t] <= state[BREAKOUT_LEVEL_KEY]:
        return {"target": 0.5 * pos, "stop": None, "take": None}
    elif pos < 0 and hist.high[t] >= state[BREAKOUT_LEVEL_KEY]:
        return {"target": 0.5 * pos, "stop": None, "take": None}

    # Check for cooldown
    if state[COOLDOWN_KEY] > 0:
