def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    ENTRY_PRICE = hist.close[-1]
    ATR_1X = ENTRY_ATR * 1.0
    ATR_2X = ENTRY_ATR * 2.0
    ATR_3X = ENTRY_ATR * 3.0
    COOLDOWN_BARS = 16
    DAILY_CAP_BARS = 960  # 64 bars per day * 15 minutes per bar

    # State management
    if 'last_entry_bar' not in state:
        state['last_entry_bar'] = -1
    if 'last_trade_date' not in state:
        state['last_trade_date'] = -1
    if 'position_size' not in state:
        state['position_size'] = 0.0
    if 'cooldown' not in state:
        state['cooldown'] = 0

    # Check for daily cap
    current_date = hist.time[-1] // (24 * 60 * 60 * 1000)
    if current_date != state['last_trade_date']:
        state['last_trade_date'] = current_date
        state['position_size'] = 0.0
        state['cooldown'] = 0

    # Check for cooldown
    if state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Donchian breakout signal
    donchian_high = ind.highest(hist.high, 96)[-1]
    donchian_low = ind.lowest(hist.low, 96)[-1]
    is_long = hist.close[-1] > donchian_high
    is_short = hist.close[-1] < donchian_low

    # HTF trend filter
    htf_close = hist.htf(60).close
    htf_ema = ind.ema(htf_close, 50)[-1]
    is_trend_up = htf_close[-1] > htf_ema
    is_trend_down = htf_close[-1] < htf_ema

    # Entry conditions
    if (is_long and is_trend_up) or (is_short and is_trend_down):
        if pos == 0:
            state['last_entry_bar'] = len(hist) - 1
            state['position_size'] = 0.25
            state['cooldown'] = COOLDOWN_BARS
            return {"target": 0.25, "stop": ENTRY_PRICE - ATR_1X, "take": ENTRY_PRICE + ATR_2X}
        elif pos < 0.25:
            state['position_size'] += 0.25
            return {"target": state['position_size'], "stop": None, "take": None}
        elif pos < 0.5:
            state['position_size'] += 0.25
            return {"target": state['position_size'], "stop": None, "take": None}

    # Exit conditions
    if pos > 0:
        if hist.low[-1] <= ENTRY_PRICE - ATR_1X:
            return {"target": 0, "stop": None, "take": None}
        if hist.high[-1] >= ENTRY_PRICE + ATR_2X:
            return {"target": 0, "stop": None, "take": None}
    elif pos < 0:
        if hist.high[-1] >= ENTRY_PRICE + ATR_1X:
            return {"target": 0, "stop": None, "take": None}
        if hist.low[-1] <= ENTRY_PRICE - ATR_2X:
            return {"target": 0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

