import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    # Signal: RSI(7) crosses back up through 20
    rsi = ind.rsi(hist.close, 7)
    signal = (rsi[-2] < 20) and (rsi[-1] >= 20)

    # Direction: Long only
    if signal and pos == 0:
        target = 1.0
    elif not signal and pos != 0:
        target = 0.0
    else:
        target = pos

    # No filter

    # Sizing: 75% of equity
    entry_price = hist.close[-1]
    entry_atr = ind.atr(hist, 14)[-1]
    position_fraction = 0.75 * entry_price / (1 * entry_atr)
    position_fraction = max(0.05, min(1.0, position_fraction))

    # Risk management
    if 'entry_price' not in state:
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['stop_price'] = entry_price - 1.5 * entry_atr
        state['take_price'] = entry_price + 2 * entry_atr
        state['cooldown'] = 0

    if state['cooldown'] > 0:
        state['cooldown'] -= 1
        return {"target": pos, "stop": None, "take": None}

    if pos != 0:
        current_price = hist.close[-1]
        current_atr = ind.atr(hist, 14)[-1]

        # Breakeven
        if current_price >= state['entry_price'] + 0.5 * state['entry_atr']:
            state['stop_price'] = state['entry_price']

        # Trailing stop
        if pos > 0:
            trailing_high = max(hist.high[:len(hist)-1])
            state['stop_price'] = max(state['stop_price'], trailing_high - 1.5 * state['entry_atr'])
        else:
            trailing_low = min(hist.low[:len(hist)-1])
            state['stop_price'] = min(state['stop_price'], trailing_low + 1.5 * state['entry_atr'])

        # Take profit
        if current_price >= state['entry_price'] + 1 * state['entry_atr']:
            state['target'] = 0.5 * pos
            state['take_price'] = state['entry_price'] + 2 * state['entry_atr']

        # Close at market open if flat
        if pos == 0:
            return {"target": 0.0, "stop": None, "take": None}

    return {"target": target, "stop": state['stop_price'], "take": state['take_price']}

