        state['entry_atr'] = entry_atr
        state['stop_price'] = entry_price - 2 * entry_atr
        state['take_price'] = entry_price + 2 * entry_atr
        state['last_add_price'] = entry_price
        state['last_add_time'] = hist.time[-1]

