        state['stop_price'] = max(state['stop_price'], entry_price - 2 * state['entry_atr'])
        state['stop_price'] = min(state['stop_price'], hist.low[-1])
        state['take_price'] = min(state['take_price'], entry_price + 2 * state['entry_atr'])
        state['take_price'] = max(state['take_price'], hist.high[-1])
    elif pos < 0:
        if hist.close[-1] <= state['entry_price'] - 2 * state['entry_atr']:
            state['stop_price'] = state['entry_price']
        if hist.close[-1] <= state['take_price']:
            target = 0.0
        state['stop_price'] = min(state['stop_price'], entry_price + 2 * state['entry_atr'])
        state['stop_price'] = max(state['stop_price'], hist.high[-1])
        state['take_price'] = max(state['take_price'], entry_price - 2 * state['entry_atr'])
        state['take_price'] = min(state['take_price'], hist.low[-1])

