        state[ENTRY_PRICE_KEY] = None
    if COOLDOWN_KEY not in state:
        state[COOLDOWN_KEY] = 0
    if LAST_ENTRY_KEY not in state:
        state[LAST_ENTRY_KEY] = None
    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = False
    if DAILY_CAP_COUNT_KEY not in state:
        state[DAILY_CAP_COUNT_KEY] = 0

    # Check daily cap
    if state[DAILY_CAP_KEY]:
        if hist.time[t] // (24 * 3600 * 1000) != state[LAST_ENTRY_KEY] // (24 * 3600 * 1000):
            state[DAILY_CAP_KEY] = False
            state[DAILY_CAP_COUNT_KEY] = 0
        else:
            state[DAILY_CAP_COUNT_KEY] += 1
            if state[DAILY_CAP_COUNT_KEY] >= 1:
                return {"target": pos, "stop": None, "take": None}

    # Calculate entry ATR and entry price
    if state[ENTRY_ATR_KEY] is None:
        entry_atr = ind.atr(hist, 14)[-1]
        entry_price = hist.close[-1]
        state[ENTRY_ATR_KEY] = entry_atr
        state[ENTRY_PRICE_KEY] = entry_price
        state[LAST_ENTRY_KEY] = hist.time[t]

    # Calculate box
    box_high = ind.highest(hist.high, 64)[-1]
    box_low = ind.lowest(hist.low, 64)[-1]
    box_height = box_high - box_low

    # Check if box is valid
    if box_height > 4 * state[ENTRY_ATR_KEY]:
        return {"target": pos, "stop": None, "take": None}

    # Determine target and stop
    if hist.close[-1] > box_high:
        target = 1.0
        stop = state[ENTRY_PRICE_KEY] - 1.5 * state[ENTRY_ATR_KEY]
    elif hist.close[-1] < box_low:
        target = -1.0
        stop = state[ENTRY_PRICE_KEY] + 1.5 * state[ENTRY_ATR_KEY]
    else:
        return {"target": pos, "stop": None, "take": None}

    # Check for partial take
    if hist.close[-1] >= state[ENTRY_PRICE_KEY] + 3 * state[ENTRY_ATR_KEY]:
        target = 0.5

    # Check for cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for daily cap
    if not state[DAILY_CAP_KEY]:
        if hist.time[t] // (24 * 3600 * 1000) != state[LAST_ENTRY_KEY] // (24 * 3600 * 1000):
            state[DAILY_CAP_KEY] = True
            state[DAILY_CAP_COUNT_KEY] = 1
        else:
            state[DAILY_CAP_COUNT_KEY] += 1

    return {"target": target, "stop": stop, "take": None}

