def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR_KEY = 'entry_atr'
    ENTRY_PRICE_KEY = 'entry_price'
    LAST_SIGNAL_KEY = 'last_signal'
    COOLDOWN_KEY = 'cooldown'
    DAILY_CAP_KEY = 'daily_cap'
    DAILY_CAP_COUNT_KEY = 'daily_cap_count'

    # Get current bar index
    t = len(hist) - 1

    # Initialize state if not already initialized
    if ENTRY_ATR_KEY not in state:
        state[ENTRY_ATR_KEY] = None
    if ENTRY_PRICE_KEY not in state:
        state[ENTRY_PRICE_KEY] = None
    if LAST_SIGNAL_KEY not in state:
        state[LAST_SIGNAL_KEY] = None
    if COOLDOWN_KEY not in state:
        state[COOLDOWN_KEY] = 0
    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = 0
    if DAILY_CAP_COUNT_KEY not in state:
        state[DAILY_CAP_COUNT_KEY] = 0

    # Check daily cap
    if state[DAILY_CAP_KEY] == 1 and state[DAILY_CAP_COUNT_KEY] >= 1:
        return {"target": pos, "stop": None, "take": None}

    # Calculate entry ATR and box
    atr = ind.atr(hist, 14)[-1]
    high_64 = ind.highest(hist.high, 64)[-1]
    low_64 = ind.lowest(hist.low, 64)[-1]
    box_height = high_64 - low_64

    # Check for breakout
    if box_height <= 4 * atr and hist.close[-1] > high_64:
        if pos == 0:
            state[ENTRY_ATR_KEY] = atr
            state[ENTRY_PRICE_KEY] = hist.close[-1]
            state[LAST_SIGNAL_KEY] = 'long'
            state[COOLDOWN_KEY] = 4
            state[DAILY_CAP_COUNT_KEY] += 1
            return {"target": 0.5, "stop": state[ENTRY_PRICE_KEY] - 2 * atr, "take": state[ENTRY_PRICE_KEY] + 3 * atr}
    elif box_height <= 4 * atr and hist.close[-1] < low_64:
        if pos == 0:
            state[ENTRY_ATR_KEY] = atr
            state[ENTRY_PRICE_KEY] = hist.close[-1]
            state[LAST_SIGNAL_KEY] = 'short'
            state[COOLDOWN_KEY] = 4
            state[DAILY_CAP_COUNT_KEY] += 1
            return {"target": -0.5, "stop": state[ENTRY_PRICE_KEY] + 2 * atr, "take": state[ENTRY_PRICE_KEY] - 3 * atr}

    # Check for cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        return {"target": pos, "stop": None, "take": None}

    # Check for opposite signal
    if state[LAST_SIGNAL_KEY] == 'long' and hist.close[-1] < state[ENTRY_PRICE_KEY]:
        return {"target": 0, "stop": None, "take": None}
    elif state[LAST_SIGNAL_KEY] == 'short' and hist.close[-1] > state[ENTRY_PRICE_KEY]:
        return {"target": 0, "stop": None, "take": None}

    # Check for ratcheting
    if state[LAST_SIGNAL_KEY] == 'long' and hist.close[-1] >= state[ENTRY_PRICE_KEY] + state[ENTRY_ATR_KEY]:
        return {"target": pos + 0.5, "stop": state[ENTRY_PRICE_KEY] - 2 * atr, "take": state[ENTRY_PRICE_KEY] + 3 * atr}
    elif state[LAST_SIGNAL_KEY] == 'short' and hist.close[-1] <= state[ENTRY_PRICE_KEY] - state[ENTRY_ATR_KEY]:
        return {"target": pos - 0.5, "stop": state[ENTRY_PRICE_KEY] + 2 * atr, "take": state[ENTRY_PRICE_KEY] - 3 * atr}

    # Return no change if no signal
    return {"target": pos, "stop": None, "take": None}

