def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR = ind.atr(hist, 14)[-1]
    ENTRY_PRICE = hist.close[-1]
    MAX_ADDS = 2
    MAX_POSITION = 1.0
    MIN_POSITION = 0.05
    DAILY_CAP = 1

    # State management
    if 'last_entry' not in state:
        state['last_entry'] = None
    if 'daily_count' not in state:
        state['daily_count'] = 0

    # Daily cap check
    if state['daily_count'] >= DAILY_CAP:
        return {"target": pos, "stop": None, "take": None}

    # Breakout and retest signal
    breakout_high = ind.highest(hist.close, 96)[-1]
    if breakout_high != state['last_entry']:
        state['last_entry'] = breakout_high
        state['daily_count'] += 1
        state['position'] = 0.25
        state['stop'] = ENTRY_PRICE - ENTRY_ATR
        state['take'] = ENTRY_PRICE + 2 * ENTRY_ATR
        state['add_count'] = 1
    else:
        if hist.low[-1] <= breakout_high:
            if pos == 0:
                state['position'] = 0.25
                state['stop'] = ENTRY_PRICE - ENTRY_ATR
                state['take'] = ENTRY_PRICE + 2 * ENTRY_ATR
                state['add_count'] = 1
            else:
                if hist.close[-1] >= ENTRY_PRICE + state['add_count'] * ENTRY_ATR:
                    state['position'] += 0.25
                    state['add_count'] += 1
                    state['position'] = min(state['position'], MAX_POSITION)

    # Trailing stop
    if pos > 0:
        state['stop'] = max(state['stop'], ENTRY_PRICE - state['add_count'] * ENTRY_ATR)
    elif pos < 0:
        state['stop'] = min(state['stop'], ENTRY_PRICE + state['add_count'] * ENTRY_ATR)

    # Scale out
    if pos > 0 and hist.close[-1] >= ENTRY_PRICE + 1.5 * ENTRY_ATR:
        state['position'] /= 2
    elif pos < 0 and hist.close[-1] <= ENTRY_PRICE - 1.5 * ENTRY_ATR:
        state['position'] /= 2

    # Cap position
    state['position'] = max(state['position'], MIN_POSITION)
    state['position'] = min(state['position'], MAX_POSITION)

    return {"target": state['position'], "stop": state['stop'], "take": state['take']}

