def strategy(hist, state, pos, ind) -> dict:
    # Signal: Donchian channel breakout
    n = 192
    high = ind.highest(hist.high, n)
    low = ind.lowest(hist.low, n)
    signal = hist.close[-1] > high[-1]

    # Filter: Last completed 1h candle above 50-period EMA
    htf_ema = ind.ema(hist.htf(60).close, 50)
    filter_active = hist.htf(60).close[-1] > htf_ema[-1]

    # Sizing: 1% of equity per 3 ATR, capped at 1.0 and floored at 0.05
    atr = ind.atr(hist, 14)
    entry_price = hist.close[-1]
    entry_atr = atr[-1]
    target_pos = max(0.05, min(1.0, 0.01 * entry_price / (3 * entry_atr)))

    # Risk: Fixed stop 3 ATR away, breakeven at 0.5 ATR profit, cooldown for 96 bars
    if 'last_exit' not in state:
        state['last_exit'] = -math.inf
    if 'stop_price' not in state:
        state['stop_price'] = entry_price - 3 * entry_atr
    if 'breakeven_price' not in state:
        state['breakeven_price'] = entry_price + 0.5 * entry_atr
    if 'cooldown' not in state:
        state['cooldown'] = 0

    if pos == 0:
        if signal and filter_active:
            state['last_exit'] = -math.inf
            state['stop_price'] = entry_price - 3 * entry_atr
            state['breakeven_price'] = entry_price + 0.5 * entry_atr
            state['cooldown'] = 0
            return {"target": target_pos, "stop": state['stop_price'], "take": None}
    else:
        if hist.close[-1] >= state['breakeven_price']:
            state['stop_price'] = entry_price
        if hist.close[-1] <= state['stop_price']:
            state['last_exit'] = hist.time[-1]
            state['stop_price'] = entry_price - 3 * entry_atr
            state['breakeven_price'] = entry_price + 0.5 * entry_atr
            state['cooldown'] = 96
            return {"target": 0, "stop": None, "take": None}
        if state['cooldown'] > 0:
            state['cooldown'] -= 1
            return {"target": pos, "stop": state['stop_price'], "take": None}

    return {"target": pos, "stop": state['stop_price'], "take": None}

