    htf_close = hist.htf(60).close
    htf_ema = ind.ema(htf_close, 50)[-1]
    if hist.close[-1] > htf_ema:
        filter_passed = True
    else:
        filter_passed = False

    # Sizing: Fixed fraction of equity
    if 'equity' not in state:
        state['equity'] = hist.close[-1] * 100000  # Assuming $100,000 equity
    position_fraction = 0.5
    if pos == 0 and filter_passed:
        target = position_fraction

    # Risk: Trailing stop, box shift, and daily cap
    if 'entry_price' not in state:
        state['entry_price'] = hist.close[-1]
        state['entry_atr'] = ind.atr(hist, 14)[-1]
        state['last_add_price'] = hist.close[-1]
        state['last_add_bar'] = -1
        state['bars_since_signal'] = 0

    if pos > 0:
        # Trailing stop
        trailing_stop = state['entry_price'] - 4 * state['entry_atr']
        if hist.low[-1] <= trailing_stop:
            target = 0.0

        # Box shift
        box_top = state['entry_price'] + 3 * state['entry_atr']
        box_bottom = state['entry_price'] - 2 * state['entry_atr']
        if hist.close[-1] >= box_top + 2 * state['entry_atr']:
            box_top += 2 * state['entry_atr']
            box_bottom += 2 * state['entry_atr']

        # Partial take
        if hist.close[-1] >= state['entry_price'] + 1.5 * state['entry_atr']:
            target = pos / 2

        # Daily cap
        if 'last_entry_day' not in state:
            state['last_entry_day'] = hist.time[-1] // (24 * 3600 * 1000)
        if hist.time[-1] // (24 * 3600 * 1000) != state['last_entry_day']:
            state['last_entry_day'] = hist.time[-1] // (24 * 3600 * 1000)
            state['bars_since_signal'] = 0
        else:
            state['bars_since_signal'] += 1
            if state['bars_since_signal'] >= 16:
                target = 0.0

    return {"target": target, "stop": None, "take": None}

