def strategy(hist, state, pos, ind) -> dict:
    # Constants
    ENTRY_ATR_KEY = 'entry_atr'
    COOLDOWN_KEY = 'cooldown'
    LAST_ENTRY_KEY = 'last_entry'
    DAILY_CAP_KEY = 'daily_cap'
    DAILY_CAP_COUNT_KEY = 'daily_cap_count'

    # Get current bar index
    t = len(hist) - 1

    # Initialize state if not already initialized
    if ENTRY_ATR_KEY not in state:
        state[ENTRY_ATR_KEY] = None
    if COOLDOWN_KEY not in state:
        state[COOLDOWN_KEY] = 0
    if LAST_ENTRY_KEY not in state:
        state[LAST_ENTRY_KEY] = None
    if DAILY_CAP_KEY not in state:
        state[DAILY_CAP_KEY] = False
    if DAILY_CAP_COUNT_KEY not in state:
        state[DAILY_CAP_COUNT_KEY] = 0

    # Calculate entry ATR
    if state[ENTRY_ATR_KEY] is None:
        state[ENTRY_ATR_KEY] = ind.atr(hist, 14)[-1]

    # Calculate Donchian breakout levels
    high_96 = ind.highest(hist.high, 96)[-1]
    low_96 = ind.lowest(hist.low, 96)[-1]

    # Determine signal
    if hist.close[-1] > high_96:
        signal = 1.0
    elif hist.close[-1] < low_96:
        signal = -1.0
    else:
        signal = 0.0

    # Apply cooldown
    if state[COOLDOWN_KEY] > 0:
        state[COOLDOWN_KEY] -= 1
        signal = 0.0

    # Apply daily cap
    if state[DAILY_CAP_KEY]:
        state[DAILY_CAP_COUNT_KEY] += 1
        if state[DAILY_CAP_COUNT_KEY] >= 2:
            signal = 0.0
        else:
            signal = 0.0
    else:
        state[DAILY_CAP_COUNT_KEY] = 0

    # Determine target position
    if signal != 0.0:
        if pos == 0.0:
            # New entry
            if signal == 1.0:
                state[LAST_ENTRY_KEY] = t
                state[DAILY_CAP_KEY] = True
            else:
                state[LAST_ENTRY_KEY] = t
                state[DAILY_CAP_KEY] = True
        else:
            # Existing position
            if signal == pos:
                # No change
                pass
            else:
                # Close position
                signal = 0.0

    # Determine stop and take levels
    stop = None
    take = None
    if pos != 0.0:
        entry_price = hist.close[state[LAST_ENTRY_KEY]]
        entry_atr = state[ENTRY_ATR_KEY]
        if pos > 0.0:
            stop = entry_price - entry_atr
            take = entry_price + 1.5 * entry_atr
        else:
            stop = entry_price + entry_atr
            take = entry_price - 1.5 * entry_atr

    # Round target to 0.05 grid
    if signal != 0.0:
        signal = round(signal, 2)

    return {
        "target": signal,
        "stop": stop,
        "take": take
    }

