    if pos == 0:
        if ind.highest(hist.close, 192)[-1] < ENTRY_PRICE:
            target = 1.0
            stop = ENTRY_PRICE - ATR_2X
            take = None
        elif ind.lowest(hist.close, 192)[-1] > ENTRY_PRICE:
            target = -1.0
            stop = ENTRY_PRICE + ATR_2X
            take = None
    else:
        target = pos
        stop = None
        take = None

    # Filter
    if pos == 0:
        if pos > 0 and ind.ema(hist.close, 20)[-1] < ind.ema(hist.close, 20)[-2]:
            target = 0.0
        elif pos < 0 and ind.ema(hist.close, 20)[-1] > ind.ema(hist.close, 20)[-2]:
            target = 0.0

