def strategy(hist, state, pos, ind) -> dict:
    # Signal: RSI(21) mean reversion
    rsi = ind.rsi(hist.close, 21)
    signal = 0.0
    if rsi[-1] >= 25 and rsi[-2] < 25:
        signal = 1.0
    elif rsi[-1] <= 75 and rsi[-2] > 75:
        signal = -1.0

    # Filter: 4h trend filter
    htf_close = hist.htf(240).close
    htf_ema = ind.ema(htf_close, 20)
    if signal == 1.0 and htf_close[-1] > htf_ema[-1]:
        signal = 1.0
    elif signal == -1.0 and htf_close[-1] < htf_ema[-1]:
        signal = -1.0
    else:
        signal = 0.0

    # Sizing: fixed fraction of equity
    if signal != 0.0:
        target = signal * 0.5
    else:
        target = pos

    # Risk: trailing stop
    if 'highs' not in state:
        state['highs'] = []
    if 'lows' not in state:
        state['lows'] = []
    if 'entry_price' not in state:
        state['entry_price'] = None

    if signal != 0.0:
        state['entry_price'] = hist.close[-1]
        state['highs'] = [hist.high[-1]]
        state['lows'] = [hist.low[-1]]
    else:
        if state['entry_price'] is not None:
            state['highs'].append(hist.high[-1])
            state['lows'].append(hist.low[-1])

    if state['entry_price'] is not None:
        high = max(state['highs'])
        low = min(state['lows'])
        entry_atr = ind.atr(hist, 14)[-1]
        stop = state['entry_price'] - 3 * entry_atr if signal == 1.0 else state['entry_price'] + 3 * entry_atr
    else:
        stop = None

    return {"target": target, "stop": stop, "take": None}
